const backendResp = $input.first().json || {};
const origChallenge = $('WhatsApp Webhook Trigger').first().json.query?.['hub.challenge'] || '';

const errObj = (typeof backendResp.error === 'object' && backendResp.error !== null) ? backendResp.error : {};
const rawStatus = backendResp.statusCode || backendResp.status || errObj.status || errObj.statusCode;

if (backendResp.error || rawStatus >= 400) {
  const httpStatus = (rawStatus && rawStatus >= 400 && rawStatus < 500) ? 403 : 503;
  return [{
    json: {
      isDirectResponse: true,
      statusCode: httpStatus,
      contentType: 'text/plain',
      bodyText: httpStatus === 403 ? 'Forbidden' : 'Service Temporarily Unavailable'
    }
  }];
}

// On success, backend returns the raw challenge string
let challengeText = backendResp.data || backendResp.response || backendResp;
if (typeof challengeText !== 'string') {
  challengeText = origChallenge;
}

return [{
  json: {
    isDirectResponse: true,
    statusCode: 200,
    contentType: 'text/plain',
    bodyText: challengeText
  }
}];
